from collections import Counter

def majority_vote(answers: list) -> str:
    """Return the most common answer; ties broken by first occurrence in answers."""
    counts = Counter(answers)
    max_count = max(counts.values())
    for a in answers:
        if counts[a] == max_count:
            return a

print(majority_vote(['42', '41', '42', '42', '40']))

from collections import Counter

def majority_vote(answers: list) -> str:
    counts = Counter(answers)
    max_count = max(counts.values())
    for a in answers:
        if counts[a] == max_count:
            return a

def vote_confidence(answers: list) -> float:
    """Percent of samples that agree with the majority answer."""
    winner = majority_vote(answers)
    counts = Counter(answers)
    return round(counts[winner] / len(answers) * 100, 1)

print(vote_confidence(['42', '41', '42', '42', '40']))
